  className?: string
  /**
   * Alert dialog size tier (`sm` | `default` | `lg` | `xl` | `full`) controlling width, padding, and density.
   * @default "default"
   */
  size?: AlertDialogSize
}

function AlertDialogContent({
  className,
  size = "default",
  children,
  ...props
