        "cn-card-description text-neutral-text-secondary text-sm group-data-[size=sm]/card:text-xs",
        className
      )}
      {...props}
    />
  )
}

function CardAction({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="card-action"
