          aria-hidden="true"
        />
      )}
    </ToastPrimitive.Close>
  )
}

function ToastIcon({ type }: { type: string | undefined }) {
  let icon: React.ReactNode = null

  if (type === "success") {
    icon = (
      <CircleCheck
        aria-hidden="true"
      />
    )
  }

  if (type === "info") {
    icon = (
      <Info
        aria-hidden="true"
      />
    )
  }

  if (type === "warning") {
    icon = (
      <TriangleAlert
